import { groupTrend, categoryBreakdown } from './analytics.mjs?v=20261104.2';
import { compact, money, range } from './utilities.mjs?v=20261104.2';
import { landPath } from './world-land.mjs?v=20261104.2';

const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct = n => new Intl.NumberFormat('en-MY',{style:'percent',maximumFractionDigits:1}).format(n);
const monthName = value => new Date(value+'-01T12:00:00Z').toLocaleDateString('en-GB',{month:'short',year:'numeric',timeZone:'UTC'});
const number = value => new Intl.NumberFormat('en-MY',{maximumFractionDigits:0}).format(value);
const colors = ['#8057ff','#88f9c0','#b3a0ff','#d4b2ff','#5bca9a','#9873ff','#c2fadd','#6e56c9','#a9b4f5','#b8dac9'];

export function dashboard(s, rows, context) {
  const {filters,trendRows,previousRows,comparisonRows,units,scenarioRate} = context;
  const previous = previousRows.reduce((a,r)=>a+r.amount,0);
  const change = previous > 0 ? (s.total-previous)/previous : null;
  const countries=s.activeUnitCount;
  const continents = new Set(s.unitStats.map(u=>u.continent).filter(c=>c&&c!=='Unspecified'));
  const eligible=s.opportunities.reduce((a,v)=>a+v.eligibleSpend,0);
  const categories=categoryBreakdown(rows);
  const top5 = s.vendorStats.slice(0,5).reduce((a,v)=>a+Math.max(0,v.total),0);
  return `<div class="dashboard-intro"><div class="dashboard-tabs"><span class="selected-tab">Portfolio overview</span><span class="dashboard-scope">${countries} ${countries===1?'country':'countries'} <span>·</span> ${continents.size} ${continents.size===1?'continent':'continents'}</span></div><span class="data-stamp"><i></i>${context.demo?'SYNTHETIC DATA':'BROWSER-LOCAL DATA'} <span>/</span> MYR</span></div>
  <section class="stats-grid dashboard-stats" aria-label="Spend at a glance">
    <article class="stat-card"><div class="stat-top"><span>Net spend</span><span class="metric-icon">↗</span></div><div class="stat-value">${compact(s.total)}</div><div class="stat-bottom">${change!==null?`<span class="delta ${change<=0?'down':'up'}">${change>0?'↗':'↘'} ${pct(Math.abs(change))}</span><span>vs. same months last year</span>`:'<span>Net of credits · current scope</span>'}</div></article>
    <article class="stat-card"><div class="stat-top"><span>Shared-supplier spend</span><span class="metric-icon">⋈</span></div><div class="stat-value">${compact(s.sharedSpend)}</div><div class="stat-bottom"><span class="mint">${pct(s.total>0?s.sharedSpend/s.total:0)}</span><span>of net spend in scope</span></div><div class="metric-track"><span style="width:${Math.min(100,Math.max(0,s.total>0?s.sharedSpend/s.total*100:0))}%"></span></div></article>
    <article class="stat-card"><div class="stat-top"><span>Supplier base</span><span class="metric-icon">◎</span></div><div class="stat-value">${number(s.vendorCount)}<span class="metric-unit">${s.vendorCount===1?'supplier':'suppliers'}</span></div><div class="stat-bottom"><span class="lavender">${s.sharedCount} shared</span><span>across 2+ countries</span></div><div class="supplier-dots" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i class="${i<s.sharedCount?'lit':''}"></i>`).join('')}</div></article>
    <article class="stat-card featured"><div class="stat-top"><span>Illustrative savings potential</span><span class="metric-icon">✧</span></div><div class="stat-value range">${s.estimatedHigh?range(s.estimatedLow,s.estimatedHigh):'RM0'}</div><div class="stat-bottom"><span>${s.opportunities.length} distinct sourcing ${s.opportunities.length===1?'opportunity':'opportunities'}</span></div><button class="metric-link" data-view="opportunities">Explore opportunities <span>↗</span></button></article>
  </section>
  <div class="analytics-primary-grid">${trendPanel(trendRows,comparisonRows,context)}${geographyPanel(s,context)}</div>
  <div class="analytics-secondary-grid">${categoryPanel(categories,s,filters)}${supplierPanel(s,top5)}${scenarioPanel(eligible,scenarioRate)}</div>
  <section class="country-strip"><div class="section-title-row"><div><h2>A connected country portfolio</h2><p>Select a country to focus the entire dashboard.</p></div><button class="text-button" data-view="units">Compare all countries ↗</button></div><div class="country-tile-grid">${units.map(u=>{const stat=s.unitStats.find(x=>x.id===u.id);return `<button class="country-tile ${filters.unit===u.id?'selected':''} ${!stat?'out-of-scope':''}" data-country="${esc(u.id)}" aria-pressed="${filters.unit===u.id}" title="Focus ${esc(u.name)}"><div class="country-tile-top"><span class="country-code">${esc(u.code)}</span><span class="country-direction">↗</span></div><strong>${esc(u.name)}</strong><small>${esc(u.continent||'Unspecified continent')}</small><span class="country-total">${stat?compact(stat.total):'—'}</span></button>`;}).join('')}</div></section>`;
}

function trendPanel(rows, comparisonRows, context) {
  let points=groupTrend(rows), previous=groupTrend(comparisonRows);
  const {filters,trendMode,compareEnabled}=context;
  const previousByMonth=new Map(previous.map(p=>[p.month.slice(5),p.total]));
  let currentRunning=0,previousRunning=0;
  const plotted=points.map(p=>{
    const prev=previousByMonth.get(p.month.slice(5))||0;
    currentRunning+=p.total;previousRunning+=prev;
    return {...p,value:trendMode==='cumulative'?currentRunning:p.total,previous:trendMode==='cumulative'?previousRunning:prev};
  });
  const w=640,h=215,left=52,right=20,top=22,bottom=29;
  const values=plotted.flatMap(p=>compareEnabled?[p.value,p.previous]:[p.value]);
  const max=Math.max(100,...values), min=Math.min(0,...values);
  const y=v=>top+(max-v)/(max-min)*(h-top-bottom);
  const x=i=>left+(plotted.length>1?i/(plotted.length-1):.5)*(w-left-right);
  const path=field=>plotted.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p[field]).toFixed(1)}`).join(' ');
  const area=plotted.length?`${path('value')} L${x(plotted.length-1)},${y(0)} L${x(0)},${y(0)} Z`:'';
  const total=rows.reduce((a,r)=>a+r.amount,0);
  const hasPrevious=compareEnabled&&comparisonRows.length>0;
  return `<section class="panel trend-panel" aria-label="Monthly spend explorer"><div class="panel-header"><div><h2>Spend over time <span class="heading-dot"></span></h2><p class="panel-subtitle">${trendMode==='cumulative'?'Cumulative':'Monthly'} net spend · full reporting period</p></div><div class="segmented-control" aria-label="Trend display"><button data-trend="monthly" aria-pressed="${trendMode==='monthly'}" class="${trendMode==='monthly'?'active':''}">Monthly</button><button data-trend="cumulative" aria-pressed="${trendMode==='cumulative'}" class="${trendMode==='cumulative'?'active':''}">Cumulative</button></div></div><div class="trend-summary"><strong>${compact(total)}</strong><div class="chart-legend"><span><i class="legend-line"></i>${filters.period==='all'?'Selected periods':esc(filters.period)}</span><button id="compare-toggle" aria-pressed="${compareEnabled&&filters.period!=='all'}" ${filters.period==='all'?'disabled':''} title="Toggle same-month prior year comparison"><i class="legend-line mint-line ${compareEnabled?'':'muted-line'}"></i>Prior year ${compareEnabled&&filters.period!=='all'?'✓':'+'}</button></div></div>${plotted.length?`<div class="trend-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(trendMode)} spend by month; use the month buttons below to filter"><defs><linearGradient id="trend-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6331fb" stop-opacity=".38"/><stop offset="1" stop-color="#6331fb" stop-opacity="0"/></linearGradient></defs>${Array.from({length:4},(_,i)=>{const v=min+(max-min)*(i/3);return `<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" class="chart-gridline"/><text x="${left-9}" y="${y(v)+3}" text-anchor="end" class="axis-label">${compact(v).replace('RM','')}</text>`;}).join('')}<path d="${area}" fill="url(#trend-fill)"/>${hasPrevious?`<path d="${path('previous')}" class="comparison-line"/>`:''}<path d="${path('value')}" class="spend-line"/>${plotted.map((p,i)=>`<g class="chart-point ${filters.month===p.month?'selected':''}"><line x1="${x(i)}" x2="${x(i)}" y1="${top}" y2="${h-bottom}"/><circle cx="${x(i)}" cy="${y(p.value)}" r="${filters.month===p.month?5:3.5}"/><title>${monthName(p.month)}: ${money(p.value)}${hasPrevious?`; prior year ${money(p.previous)}`:''}</title></g>`).join('')}</svg><div class="month-buttons" style="--months:${plotted.length}">${plotted.map(p=>`<button data-month="${p.month}" aria-pressed="${filters.month===p.month}" class="${filters.month===p.month?'active':''}" title="${monthName(p.month)} · ${money(p.total)}">${monthName(p.month).split(' ')[0]}${filters.period==='all'?`<small>${p.month.slice(2,4)}</small>`:''}</button>`).join('')}</div></div>`:'<div class="chart-empty">No spend in this reporting scope.</div>'}<div class="chart-footnote"><span><span class="tiny-cross">⌖</span> Click a month to focus all analysis</span><span>${hasPrevious?'Prior year aligned to the same months':filters.period==='all'?'Comparison disabled across multiple years':'No prior-year comparison in scope'}</span></div></section>`;
}

function geographyPanel(s,context) {
  const {units,filters}=context;
  const allContinents=[...new Set(units.map(u=>u.continent).filter(c=>c&&c!=='Unspecified'))];
  const data=s.unitStats.filter(u=>Number.isFinite(u.lat)&&Number.isFinite(u.lon));
  const max=Math.max(1,...data.map(u=>u.total));
  const mapX=lon=>(lon+180)*2,mapY=lat=>(85-lat)*2.1;
  return `<section class="panel geo-panel" aria-label="Global spend footprint"><div class="panel-header"><div><h2>Your global footprint</h2><p class="panel-subtitle">${s.activeUnitCount} ${s.activeUnitCount===1?'country':'countries'} across ${new Set(s.unitStats.map(u=>u.continent).filter(c=>c&&c!=='Unspecified')).size} known continents.</p></div><span class="geo-symbol">◎</span></div><div class="world-map"><svg viewBox="0 0 720 315" aria-label="World map with country spend markers" role="group"><defs><pattern id="land-dots" width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1.15" fill="#46405f"/></pattern><radialGradient id="map-glow"><stop stop-color="#6331fb" stop-opacity=".18"/><stop offset="1" stop-color="#6331fb" stop-opacity="0"/></radialGradient><clipPath id="map-window"><rect width="720" height="315"/></clipPath></defs><g clip-path="url(#map-window)"><ellipse cx="376" cy="164" rx="325" ry="155" fill="url(#map-glow)"/>${[60,120,180,240,300].map(y=>`<line x1="0" x2="720" y1="${y}" y2="${y}" class="map-gridline"/>`).join('')}${[120,240,360,480,600].map(x=>`<line x1="${x}" x2="${x}" y1="0" y2="315" class="map-gridline"/>`).join('')}<path d="${landPath}" fill="url(#land-dots)" stroke="#302841" stroke-width=".6"/>${data.length>1?data.slice(1).map(u=>{const first=data[0];const x1=mapX(first.lon),y1=mapY(first.lat),x2=mapX(u.lon),y2=mapY(u.lat);return `<path d="M${x1} ${y1} Q${(x1+x2)/2} ${Math.min(y1,y2)-Math.abs(x2-x1)*.13} ${x2} ${y2}" class="map-connection"/>`;}).join(''):''}${data.map(u=>{const x=mapX(u.lon),y=mapY(u.lat),r=3+Math.sqrt(Math.max(0,u.total)/max)*3.3;return `<g class="map-marker ${filters.unit===u.id?'selected':''}" data-country="${esc(u.id)}" role="button" tabindex="0" aria-label="Focus ${esc(u.name)}, ${money(u.total)}"><circle class="marker-halo" cx="${x}" cy="${y}" r="${r+6}"/><circle class="marker-dot" cx="${x}" cy="${y}" r="${r}"/><title>${esc(u.name)} · ${money(u.total)}</title><g class="map-label"><rect x="${Math.min(580,Math.max(5,x-55))}" y="${y+15}" width="115" height="38" rx="5"/><text x="${Math.min(580,Math.max(5,x-55))+9}" y="${y+30}">${esc(u.code)} · ${compact(u.total)}</text></g></g>`;}).join('')}</g></svg>${!data.length?'<div class="map-no-geography">No mapped countries in this selection.</div>':''}</div><div class="continent-switches">${allContinents.map((name,i)=>{const matching=s.unitStats.filter(u=>u.continent===name),total=matching.reduce((a,u)=>a+u.total,0);return `<button class="continent-button ${filters.continent===name?'active':''}" data-continent="${esc(name)}" aria-pressed="${filters.continent===name}"><span class="continent-name"><i style="background:${colors[i]}"></i>${esc(name)}<span class="continent-count">${matching.length}</span></span><strong>${compact(total)}</strong><span class="continent-bar"><i style="width:${Math.min(100,Math.max(0,s.total>0?total/s.total*100:0))}%;background:${colors[i]}"></i></span></button>`;}).join('')}</div><div class="map-caption"><span>Country markers show relative spend</span><span>Click to isolate ↗</span></div></section>`;
}

function categoryPanel(categories,s,filters) {
  const max=Math.max(1,...categories.map(c=>c.total));
  return `<section class="panel category-panel"><div class="panel-header"><div><h2>Category mix</h2><p class="panel-subtitle">${categories.length>6?'Largest 6 of '+categories.length+' categories':'What your portfolio buys'}</p></div><span class="pill">${categories.length} categories</span></div><div class="category-bars">${categories.slice(0,6).map((c,i)=>`<button class="category-row ${filters.category===c.name?'active':''}" data-category="${esc(c.name)}" aria-pressed="${filters.category===c.name}"><span class="category-row-top"><span>${esc(c.name)}</span><strong>${compact(c.total)}</strong></span><span class="category-bar-track"><i style="width:${Math.max(0,c.total/max*100)}%;background:${colors[i%colors.length]}"></i></span><span class="category-percent">${pct(s.total>0?c.total/s.total:0)} of scoped spend</span></button>`).join('')||'<p class="panel-subtitle">No categories in scope.</p>'}</div><div class="panel-bottom-note">Select a category to focus your portfolio ↗</div></section>`;
}

function supplierPanel(s,top5) {
  const concentration=s.positiveSpend>0?top5/s.positiveSpend:0;
  const r=43,c=2*Math.PI*r;
  return `<section class="panel supplier-panel"><div class="panel-header"><div><h2>Supplier concentration</h2><p class="panel-subtitle">Where your buying power sits</p></div><button class="text-button" data-view="overlap" aria-label="Explore all suppliers">↗</button></div><div class="concentration-summary"><svg viewBox="0 0 110 110" role="img" aria-label="Top five suppliers ${pct(concentration)} of positive supplier spend"><circle cx="55" cy="55" r="${r}" class="donut-track"/><circle cx="55" cy="55" r="${r}" class="donut-value" stroke-dasharray="${concentration*c} ${c}" transform="rotate(-90 55 55)"/><text x="55" y="53" text-anchor="middle" class="donut-text">${pct(concentration)}</text><text x="55" y="68" text-anchor="middle" class="donut-subtext">TOP FIVE</text></svg><div><strong>${compact(top5)}</strong><span>with your five largest suppliers</span><small>Share of positive net supplier spend</small></div></div><div class="top-supplier-list">${s.vendorStats.slice(0,5).map((v,i)=>`<button data-vendor="${esc(v.id)}"><span class="supplier-rank">0${i+1}</span><span>${esc(v.name)}<small>${v.unitCount} ${v.unitCount===1?'country':'countries'}</small></span><strong>${compact(v.total)}</strong><span class="supplier-arrow">↗</span></button>`).join('')||'<p class="panel-subtitle">No suppliers in scope.</p>'}</div></section>`;
}

function scenarioPanel(eligible,rate) {
  return `<section class="panel scenario-panel"><div class="panel-header"><div><span class="eyebrow">WHAT IF EXPLORER</span><h2>Put your scale to work.</h2><p class="panel-subtitle">Model a coordinated buying scenario.</p></div><span class="scenario-star">✧</span></div><div class="scenario-body"><div class="scenario-equation"><span>Assumed improvement</span><output id="scenario-rate-output" for="scenario-rate">${rate}%</output></div><input id="scenario-rate" type="range" min="1" max="12" step=".5" value="${rate}" aria-label="Assumed improvement rate" style="--progress:${(rate-1)/11*100}%"><div class="range-bounds"><span>1%</span><span>12%</span></div><div class="scenario-result"><small>Illustrative potential</small><strong id="scenario-result" aria-live="polite">${compact(Math.round(eligible*rate/100))}</strong><span>on ${compact(eligible)} eligible shared-supplier spend</span></div><p>One adjustable assumption across distinct supplier opportunities. This scenario is separate from the vendor-specific estimate above.</p><button class="button button-mint wide-button" data-view="opportunities">Explore the sourcing moves <span>↗</span></button><small class="scenario-disclaimer">Scenario estimate · not a committed or realized saving</small></div></section>`;
}
